// FUNCTION: BFME2 0x001DFC2A size=168 name=?Rva001DFC2AParse@@YAXPAVINI@@PAX1PBX@Z evidence=?:placeholder tier=A
// TintDrawableFXNugget's Color field: R, G and B as signed integers (-255..255), scaled to 0..1.
void parseTintColor(INI *ini, void *instance, void *store, const void *userData)
{
	const char *names[3] = { "R", "G", "B" };
	Int colors[3];
	for (Int i = 0; i < 3; ++i)
	{
		Int value = ini->scanInt(ini->getNextSubToken(names[i]));
		colors[i] = value;
		if (value < -255 || value > 255)
			throw INIException(3, "color value %s=%i out of range (0..255)", names[i], value);
	}
	RGBColor *color = (RGBColor *)store;
	color->red = colors[0] * (1.0f / 255.0f);
	color->green = colors[1] * (1.0f / 255.0f);
	color->blue = colors[2] * (1.0f / 255.0f);
}

