// FUNCTION: BFME2 0x001DFD57 size=255 name=?parseCullingInfo@FXList@@SAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=A
void FXList::parseCullingInfo(INI *ini, void *instance, void *store, const void *userData)
{
	FXList *self = (FXList *)instance;
	for (const char *token = ini->getNextTokenOrNull(ini->getSepsColon()); token != NULL;
		token = ini->getNextTokenOrNull(ini->getSepsColon()))
	{
		if (FXListCRT::_strcmpi(token, "TrackingSeconds") == 0)
			self->m_cullTrackingTime = (UnsignedInt)(ini->scanReal(ini->getNextToken()) * BfmeLogicFramesPerSecond);
		else if (FXListCRT::_strcmpi(token, "StartCullingAbove") == 0)
			self->m_cullTrackingMin = ini->scanUnsignedInt(ini->getNextToken());
		else if (FXListCRT::_strcmpi(token, "CullAllAbove") == 0)
			self->m_cullTrackingMax = ini->scanUnsignedInt(ini->getNextToken());
		else
			throw INIException(3, "bad colon spacing, or unexpected token in FXList::parseCullingInfo");
	}

	if (self->m_cullTrackingMax == 0)
		throw INIException(3, "m_cullTrackingMax == 0 in FXList::parseCullingInfo");
	if (self->m_cullTrackingMin == 0)
		throw INIException(3, "m_cullTrackingMin == 0 in FXList::parseCullingInfo");
	if (self->m_cullTrackingMax <= self->m_cullTrackingMin)
		self->m_cullTrackingMax = self->m_cullTrackingMin + 1;
}

