void EvaEventFXNugget::doFXObj(const Object *primary, const Object *secondary) const
{
	if (primary == NULL)
		return;

	Player *owner = primary->getControllingPlayer();
	if (owner != NULL && owner->isLocalPlayer())
	{
		TheEva->reportEvaEvent((EvaEventID)m_evaEventOwner, primary->getPosition(), NULL);
		return;
	}
	Player *local = ThePlayerList->getLocalPlayer();
	if (local != NULL && local->getRelationship(primary->getTeam()) == ALLIES)
	{
		TheEva->reportEvaEvent((EvaEventID)m_evaEventAlly, primary->getPosition(), NULL);
		return;
	}
	TheEva->reportEvaEvent((EvaEventID)m_evaEventEnemy, primary->getPosition(), NULL);
}

