// FUNCTION: BFME2 0x001E04FE size=251 name=?doFXPos@LaserFXNugget@@UBEXPBVCoord3D@@PBVMatrix3D@@M0@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void LaserFXNugget::doFXPos(const Coord3D *primary, const Matrix3D *primaryMtx, Real primarySpeed, const Coord3D *secondary) const
{
	if (primary)
	{
		const ThingTemplate *tmpl = TheThingFactory->findTemplate(m_laserName);
		Drawable *draw = TheThingFactory->newDrawable(tmpl, 0, -1);
		if (draw)
		{
			static NameKeyType key_LaserUpdate = TheNameKeyGenerator->nameToKey("LaserUpdate");
			LaserUpdate *update = (LaserUpdate *)draw->findClientUpdateModule(key_LaserUpdate);
			if (update)
			{
				Coord3D position;
				if (secondary)
				{
					update->initLaser(0, primary, secondary, 0);
				}
				else
				{
					position.set(primary);
					position.add(&m_targetPositionOffsetFallback);
					if (!m_laserBackwards)
						update->initLaser(0, primary, &position, 0);
					else
						update->initLaser(0, &position, primary, 0);
				}
			}
		}
	}
}

// FUNCTION: BFME2 0x001E05F9 size=283 name=?doFXObj@LaserFXNugget@@UBEXPBVObject@@0@Z evidence=N:ledger tier=A
void LaserFXNugget::doFXObj(const Object *primary, const Object *secondary) const
{
	if (primary)
	{
		const ThingTemplate *tmpl = TheThingFactory->findTemplate(m_laserName);
		Drawable *draw = TheThingFactory->newDrawable(tmpl, 0, -1);
		if (draw)
		{
			static NameKeyType key_LaserUpdate = TheNameKeyGenerator->nameToKey("LaserUpdate");
			LaserUpdate *update = (LaserUpdate *)draw->findClientUpdateModule(key_LaserUpdate);
			if (update)
			{
				if (secondary)
				{
					update->initFromDrawables((void *)primary, primary->getDrawable(), secondary->getDrawable(), 0);
				}
				else
				{
					Coord3D position;
					const Coord3D *start = primary->getPosition();
					position.set(start);
					position.add(&m_targetPositionOffsetFallback);
					if (!m_laserBackwards)
						update->initLaser(primary, start, &position, 0);
					else
						update->initLaser(primary, &position, start, 0);
				}
			}
		}
	}
}

