// FUNCTION: BFME2 0x001E281A size=71 name=?findFXList@FXListStore@@QBEPBVFXList@@PBD@Z evidence=N:ledger tier=A
const FXList *FXListStore::findFXList(const char *name) const
{
	if (FXListCRT::_strcmpi(name, "None") == 0)
		return NULL;

	_STL::hash_map<NameKeyType, FXList *, rts::hash<NameKeyType>, _STL::equal_to<NameKeyType> >::const_iterator it =
		m_fxmap.find(TheNameKeyGenerator->nameToKey(name));
	if (it != m_fxmap.end())
		return it->second;
	return NULL;
}

// FUNCTION: BFME2 0x001E296E size=170 name=?doFXPos@FXList@@QBEXPBVCoord3D@@PBVMatrix3D@@M0@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void FXList::doFXPos(const Coord3D *primary, const Matrix3D *primaryMtx, Real primarySpeed,
	const Coord3D *secondary) const
{
	const FXList *fx = this;
	while (fx->m_isRetired)
	{
		const FXList *current = TheFXListStore->findFXList(fx->m_name.str());
		if (current == NULL)
			break;
		fx = current;
	}

	if (!fx->m_playEvenIfShrouded && primary != NULL &&
		TheShroudManager->getShroudStatusForPlayer(ThePlayerList->getLocalPlayer()->getPlayerIndex(), primary) != CELLSHROUD_CLEAR)
		return;

	for (std::list<FXNugget *>::const_iterator it = fx->m_nuggets.begin(); it != fx->m_nuggets.end(); ++it)
	{
		FXNugget *nugget = *it;
		if (nugget->rva001DFF5D(NULL, NULL))
		{
			nugget->doFXPos(primary, primaryMtx, primarySpeed, secondary);
			if (nugget->m_stopIfNuggetPlayed)
				break;
		}
	}
}

// FUNCTION: BFME2 0x001E2A18 size=188 name=?doFXObj@FXList@@QBEXPBVObject@@0@Z evidence=N:ledger tier=A
void FXList::doFXObj(const Object *primary, const Object *secondary) const
{
	const FXList *fx = this;
	while (fx->m_isRetired)
	{
		const FXList *current = TheFXListStore->findFXList(fx->m_name.str());
		if (current == NULL)
			break;
		fx = current;
	}

	if (!fx->m_playEvenIfShrouded && primary != NULL)
	{
		if (primary->m_partitionData != NULL)
		{
			if ((Int)primary->getShroudStatusForPlayer(ThePlayerList->getLocalPlayer()->getPlayerIndex()) > 2)
				return;
		}
		else if (TheShroudManager->getShroudStatusForPlayer(ThePlayerList->getLocalPlayer()->getPlayerIndex(), primary->getPosition()) != CELLSHROUD_CLEAR)
			return;
	}

	for (std::list<FXNugget *>::const_iterator it = fx->m_nuggets.begin(); it != fx->m_nuggets.end(); ++it)
	{
		FXNugget *nugget = *it;
		if (nugget->rva001DFF5D((Object *)primary, (Object *)secondary))
		{
			nugget->doFXObj(primary, secondary);
			if (nugget->m_stopIfNuggetPlayed)
				break;
		}
	}
}

// FUNCTION: BFME2 0x001E2BB0 size=226 name=?rva001E2BB0@Rva001E2BB0@@QAE?AVRva000B3F15@@PBD@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x001E2CAE size=261 name=?parseFXListDefinition@FXListStore@@SAXPAVINI@@@Z evidence=N:ledger tier=A
void FXListStore::parseFXListDefinition(INI *ini)
{
	const char *name = ini->getNextToken();
	NameKeyType key = TheNameKeyGenerator->nameToKey(name);

	_STL::hash_map<NameKeyType, FXList *, rts::hash<NameKeyType>, _STL::equal_to<NameKeyType> >::iterator it =
		TheFXListStore->m_fxmap.find(key);
	if (it != TheFXListStore->m_fxmap.end() && ini->getLoadType() == INI_LOAD_RELOAD)
	{
		TheFXListStore->m_fxmap.erase(it);
		FXList *retired = it->second;
		if (retired != NULL)
		{
			retired->m_isRetired = true;
			TheFXListStore->m_retiredLists.push_back(retired);
		}
	}

	FXList *fxl = new FXList(AsciiString(name));
	TheFXListStore->m_fxmap[key] = fxl;
	ini->initFromINI(fxl, TheFXListFieldParse);
}

// FUNCTION: BFME2 0x001E2DB3 size=35 name=?doFXObj@FXListAtBonePosFXNugget@@UBEXPBVObject@@0@Z evidence=N:ledger tier=A
void FXListAtBonePosFXNugget::doFXObj(const Object *primary, const Object *secondary) const
{
	if (primary == NULL)
		return;
	doFxAtBones(primary, 0);
	doFxAtBones(primary, 1);
}

// FUNCTION: BFME2 0x001E2DD6 size=283 name=?doFxAtBones@FXListAtBonePosFXNugget@@IBEXPBVObject@@H@Z evidence=N:ledger tier=A
void FXListAtBonePosFXNugget::doFxAtBones(const Object *obj, Int pass) const
{
	enum { MAX_BONE_POINTS = 40 };
	Coord3D bonePositions[MAX_BONE_POINTS];
	Matrix3D boneTransforms[MAX_BONE_POINTS];
	Drawable *drawable = obj->getDrawable();
	if (drawable)
	{
		Int boneCount = drawable->getCurrentClientBonePositions(m_boneName.str(), pass, bonePositions, boneTransforms, MAX_BONE_POINTS);
		for (Int boneIndex = 0; boneIndex < boneCount; ++boneIndex)
		{
			Coord3D worldPosition;
			Matrix3D worldTransform;
			obj->convertBonePosToWorldPos(&bonePositions[boneIndex], &boneTransforms[boneIndex], &worldPosition, &worldTransform);
			const FXList *fxList = m_fx;
			if (fxList && !fxList->rva001E2EF1())
				fxList->doFXPos(&worldPosition, &worldTransform, 0.0f, NULL);
		}
	}
}

